package handler

import (
	"encoding/json"
	"net/http"
)

func ListItems(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated) // BUG: should not set status here (returns 201)
	json.NewEncoder(w).Encode(map[string]any{"data": []any{}}) // BUG: key should be "items"
}
